// Mechanical integration of exclusive-owner, source-self-reviewed packets.
const fs=require('fs'),z=require('zlib'),crypto=require('crypto'),assert=require('assert/strict');
const dir='docs/ssw-workspace/agriculture/',out=dir+'continuation-20261103b/',ld='docs/ssw-workspace/source-coverage-v2/',lp=ld+'agriculture.json',cp='src/data/agriculture/reader-moisture-checks.json';
const read=p=>JSON.parse(fs.readFileSync(p)),hash=v=>crypto.createHash('sha256').update(JSON.stringify(v)).digest('hex'),bytes=b=>crypto.createHash('sha256').update(b).digest('hex'),write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const base=p=>require('child_process').execFileSync('git',['show','90b0a1f47295e57639b4a076d0137c8860c2ad93:'+p],{maxBuffer:30000000});
const l=JSON.parse(base(lp)),old=structuredClone(l),checks=JSON.parse(base(cp)),oldChecks=structuredClone(checks),changed=[];
const binding=read(out+'greenhouse/co2-binding-proposal.json');
assert(!checks.checks.some(c=>c.id===binding.readerPayload.id));
assert.equal(hash(binding.readerPayload),binding.readerPayloadSha256);
checks.checks.push(binding.readerPayload);
const packets=[['soil',read(dir+'parallel-continuation-20261103/soil/proposal.json').canonicalUpdates],['soil-new',read(out+'soil/proposal.json').canonicalUpdates],['vegetables',read(dir+'parallel-continuation-20261103/vegetables/packet.json').canonicalUpdates],['facility',read(dir+'parallel-continuation-20261103/facility/packet.json').canonicalUpdates],['rice',read(out+'rice/patch-proposal.json').changes],['orchard',read(out+'orchard/unit-updates.json').updates]];
for(const [lane,updates]of packets)for(const p of updates){const i=l.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0);const before=l.knowledgeUnits[i];assert.equal(hash(before),p.beforeSha256||hash(p.before));assert(!['covered_ai','duplicate','excluded'].includes(before.status));let after=p.after?structuredClone(p.after):{...structuredClone(before),...p.patch,previousSourceRefs:p.previousSourceRefs};if(p.knowledgeId===binding.canonicalReplacement.knowledgeId){after=structuredClone(binding.canonicalReplacement.after);const ev=after.assessmentEvidence.find(e=>e.path===cp);assert(ev);ev.jsonPointer='/checks/'+checks.checks.findIndex(c=>c.id===binding.readerPayload.id);ev.sha256=hash(binding.readerPayload);}l.knowledgeUnits[i]=after;changed.push({lane,knowledgeId:p.knowledgeId,beforeStatus:before.status,afterStatus:after.status,beforeSha256:hash(before),afterSha256:hash(after)});}
for(const s of l.sources){const p=ld+`agriculture-${s.sourceId}-regions.json.gz`,a=JSON.parse(z.gunzipSync(base(p)));for(const pg of a.pages)for(const e of pg.elements){e.knowledgeIds=e.knowledgeIds.filter(id=>!changed.some(c=>c.knowledgeId===id));}for(const c of changed){const u=l.knowledgeUnits.find(u=>u.knowledgeId===c.knowledgeId);for(const r of u.sourceRefs.filter(r=>r.sourceId===s.sourceId)){const pg=a.pages.find(p=>p.pdfPage===r.pdfPage);assert(pg);for(const id of r.elementIds){const e=pg.elements.find(e=>e.elementId===id);assert(e);e.classification='knowledge';e.knowledgeIds=[...new Set([...e.knowledgeIds,u.knowledgeId])];e.reason=null;}const page=l.pages.find(p=>p.sourceId===s.sourceId&&p.pdfPage===r.pdfPage);page.regionCensus.status='visually_reviewed';page.regionCensus.visualReviewRef=u.sourceReview.reviewRef;if(page.semanticInventory.status==='pending')page.semanticInventory={status:'partial',reviewRef:u.sourceReview.reviewRef};if(page.disposition==='unclassified')page.disposition='mixed';}}const b=z.gzipSync(JSON.stringify(a),{mtime:0});fs.writeFileSync(p,b);for(const pg of l.pages.filter(p=>p.sourceId===s.sourceId))pg.regionCensus.sha256=bytes(b);}
for(const pg of l.pages)pg.knowledgeIds=l.knowledgeUnits.filter(u=>u.sourceRefs.some(r=>r.sourceId===pg.sourceId&&r.pdfPage===pg.pdfPage)).map(u=>u.knowledgeId);
for(const u of old.knowledgeUnits.filter(u=>['covered_ai','duplicate','excluded'].includes(u.status)))assert.deepEqual(l.knowledgeUnits.find(v=>v.knowledgeId===u.knowledgeId),u);
for(const c of oldChecks.checks)assert.deepEqual(checks.checks.find(v=>v.id===c.id),c);
write(lp,l);write(cp,checks);write(out+'integration.json',{schemaVersion:1,status:'integrated_pending_validation',baselineCommit:'90b0a1f47295e57639b4a076d0137c8860c2ad93',changes:changed,coveredBefore:old.knowledgeUnits.filter(u=>u.status==='covered_ai').length,coveredAfter:l.knowledgeUnits.filter(u=>u.status==='covered_ai').length,newChecks:[binding.readerPayload.id],priorAcceptedUnitsPreserved:true,priorChecksPreserved:true,sourceCoveragePercent:null,wholeSourceKnowledgeCovered:false,crossWorkerSemanticReview:false,domainReviewed:false,nativeReviewed:false,physicalDeviceTested:false,learnerDurationMeasured:false});console.log(JSON.stringify({unitChanges:changed.length,covered:l.knowledgeUnits.filter(u=>u.status==='covered_ai').length,checks:checks.checks.length}));
